// Demo: Casper Proof-of-Stake — validator selection lottery
var vals=[];for(var i=0;i<17;i++){vals.push({id:'v'+i,stake:100+((i*37+3)%900)});}
var tot=vals.reduce(function(a,v){return a+v.stake;},0);
var r=(3*7919)%tot,acc=0,winner=vals[0];
for(var i=0;i<vals.length;i++){acc+=vals[i].stake;if(r<acc){winner=vals[i];break;}}
console.log('technique: Casper Proof-of-Stake');console.log('selected validator: '+winner.id+' (stake '+winner.stake+' of '+tot+')');

